SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `green_service_runs` (`codrun` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`servico` VARCHAR(80) NOT NULL,`banco_dados` VARCHAR(100) NOT NULL,`status` VARCHAR(20) NOT NULL,`inicio_em` DATETIME NOT NULL,`fim_em` DATETIME NULL,`quantidade` INT NOT NULL DEFAULT 0,`detalhes` JSON NULL,PRIMARY KEY (`codrun`),KEY `IX_GREEN_SERVICE_RUNS` (`servico`,`banco_dados`,`inicio_em`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `registros_migracao` (`codigo_migracao`,`origem`,`destino`,`tipo`,`versao`,`status`,`quantidade_registros`,`iniciada_em`,`concluida_em`,`detalhes`) VALUES ('GREEN_WINDOWS_PHP_SERVICES_190','GreenSolutions PHP services','green_service_runs; Windows Task Scheduler','ESTRUTURA','4.0.1','CONCLUIDA',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,JSON_OBJECT('php_cli',TRUE,'schedule_windows',TRUE,'idempotente',TRUE)) ON DUPLICATE KEY UPDATE `status`=VALUES(`status`),`concluida_em`=VALUES(`concluida_em`),`detalhes`=VALUES(`detalhes`);
